CREATE VIEW [dbo].[ApparecchiNewSlot] AS SELECT 'NSL' AS Categoria ,'New Slot' AS Tipo, NULL AS IdLocale,2 AS TipoOggetto,'NSL' AS TipoOggettoDesc,IdDedicato AS CodiceOggetto,prop AS Proprieta,agente AS Associato, matricola, nome as Modello, identificativo, nullaosta, 1 AS TM, NULL AS idmove, NULL AS IdStorico, 0 as IdPadre, DataCreazione AS DataDa, NULL AS DataA, DataCreazione, fornitore, costruttore, magazzini.IdMagazzino, 0 AS Ordinamento, 0 AS OrdinamentoCategoria,magazzini.nomemagazzino AS Luogo,dedicati.idconcessionario FROM dedicati,magazzini WHERE dedicati.idmagazzino=magazzini.idmagazzino AND dedicati.DataFine IS NULL AND partipologiamonopoli=1 AND iddedicato NOT IN (SELECT dedicato FROM move WHERE move.dedicato=dedicati.iddedicato) Union SELECT 'NSL' AS Categoria ,'New Slot' AS Tipo, move.locale AS IdLocale,2 AS TipoOggetto,'NSL' AS TipoOggettoDesc,move.dedicato AS CodiceOggetto,dedicati.prop AS Proprieta,dedicati.agente AS Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, 1 AS TM, move.idmove, NULL AS IdStorico, 0 as IdPadre, move.DataCambio AS DataDa, NULL AS DataA, Dedicati.DataCreazione, dedicati.fornitore, dedicati.costruttore, dedicati.IdMagazzino, 0 AS Ordinamento, 0 AS OrdinamentoCategoria,locali.nome AS Luogo,dedicati.idconcessionario FROM move,dedicati,locali WHERE locali.idlocale=move.locale AND dedicati.iddedicato=move.dedicato AND dedicati.partipologiamonopoli=1 AND move.dedicato>0
GO
